 has_yaplus:
 type: boolean
 default: false
 has_cashback_plus:
 type: boolean
 default: false
 selected_loyalty_program:
 type: string
...
 BackendVariables:
 type: object
 additionalProperties: false
 required:
 - country_code2
 - tariff
 - zone
 - category
 - user_tags
 - user_data
 - surge_params
 - requirements
 - category_data
 - exps
